# Digital Projection dVision 35 and dVision Scope ASCII protocol (digitalprojection-dvision): ":" + mnemonic +
# value + CR, acknowledged "%" + address + mnemonic + six-character value (document p.5-7).
DVS = "digitalprojection-dvision"


def dvs(command, input, wire, **extra):
    text(DVS, command, input, wire, **extra)


