# Telemetry: acknowledges (p.6-7) and replies to the polls.
telemetry(DVS, "power", inbound="%001 POWR 000001\r", expect_state={"power": True})
telemetry(DVS, "power-state", inbound="%001 POST 000003\r", expect_state={"power_state": "on"})
