telemetry(DVS, "contrast-no-spaces", inbound="%001CNTR000059\r", expect_state={"contrast": 59})
telemetry(DVS, "serial", inbound="%001 SERI e00001 07010001\r", expect_state={"serial_number": "07010001"})
telemetry(DVS, "lamp-status", inbound="%001 LST1 000002\r", expect_state={"lamp1_status": "on"})
